prologue:
/* The game draws in 640x480, x from the left and y down from the top, whatever the window is;
   GetViewport answers in real pixels. A colour is packed as 0xAARRGGBB and the helpers below
   take the four channels from 0 to 1 */
static MOD_UNUSED uint32_t render_rgba(float r, float g, float b, float a) {
    const float channel[4] = { a, r, g, b };
    uint32_t out = 0;
    int at;
    for (at = 0; at < 4; ++at) {
        int value = (int)(channel[at] * 255.0f + 0.5f);
        if (value < 0) value = 0;
        if (value > 255) value = 255;
        out = (out << 8) | (uint32_t)value;
    }
    return out;
}

static MOD_UNUSED int render_viewport(int want_width) {
    int wide = 0, tall = 0;
    if (API->render == 0) return 0;
    API->render->GetViewport(SELF, &wide, &tall);
    return want_width ? wide : tall;
}

static MOD_UNUSED int render_ready(void) {
    return API->render != 0 && API->render->GetDevice(SELF) != 0;
}

/* The canvas is fixed, the window is not: this turns a canvas point into a window pixel */
static MOD_UNUSED float render_to_screen(float value, int is_x) {
    const float canvas = is_x ? AMOD_MENU_WIDE : AMOD_MENU_TALL;
    const int pixels = render_viewport(is_x);
    return pixels > 0 ? value * (float)pixels / canvas : value;
}

/* True once after the device has been built anew: everything made on the old one is dead */
static MOD_UNUSED int render_device_new(uint32_t* seen) {
    uint32_t now;
    if (API->render == 0) return 0;
    now = API->render->DeviceGeneration(SELF);
    if (now == *seen) return 0;
    *seen = now;
    return 1;
}

/* A menu font by its name from menu_cfg.txt; an empty name means the game's system font */
static MOD_UNUSED AmodFont render_font(const char* name) {
    if (API->render == 0 || name == 0 || name[0] == 0) return 0;
    return API->render->GetFont(SELF, name);
}

/* A picture by path: the one the game already holds, otherwise the file is read.
   What is found is remembered, but only while the same device lives: after it is
   built anew the id is dead */
static MOD_UNUSED AmodTextureId render_texture(const char* path) {
    enum { kRemember = 8 };
    static char paths[kRemember][128];
    static AmodTextureId ids[kRemember];
    static uint32_t generation;
    static int filled;
    AmodTextureId id;
    uint32_t now;
    int at;

    if (API->render == 0 || API->textures == 0 || path == 0 || path[0] == 0)
        return AMOD_INVALID_TEXTURE;

    now = API->render->DeviceGeneration(SELF);
    if (now != generation) {
        generation = now;
        filled = 0;
    }
    for (at = 0; at < filled; ++at)
        if (strcmp(paths[at], path) == 0) return ids[at];

    id = API->textures->Find(SELF, path);
    if (id == AMOD_INVALID_TEXTURE)
        id = API->textures->Load(SELF, path, 0, 1);   /* no mip levels, with alpha: menu pictures */

    if (id != AMOD_INVALID_TEXTURE && filled < kRemember && strlen(path) < sizeof paths[0]) {
        strcpy(paths[filled], path);
        ids[filled] = id;
        ++filled;
    }
    return id;
}

static MOD_UNUSED int render_texture_size(const char* path, int want_width) {
    AmodTexture info;
    const AmodTextureId id = render_texture(path);
    if (id == AMOD_INVALID_TEXTURE) return 0;
    memset(&info, 0, sizeof info);
    info.structSize = sizeof info;
    if (API->textures->Get(SELF, id, &info) == 0) return 0;
    return want_width ? info.width : info.height;
}

/* One quad of the batch. x and y are its top-left corner and the turn happens about its middle;
   an invalid texture leaves the colour alone to fill the quad, which is how a turned
   rectangle and a sloped line are drawn */
static MOD_UNUSED void render_quad(AmodTextureId texture, float x, float y, float w, float h,
                                   float degrees, uint32_t colour) {
    AmodQuad quad;
    if (API->render == 0) return;
    memset(&quad, 0, sizeof quad);
    quad.x = x;
    quad.y = y;
    quad.w = w;
    quad.h = h;
    quad.angle = degrees * 3.14159265f / 180.0f;   /* the API counts radians, clockwise */
    quad.u1 = 1.0f;
    quad.v1 = 1.0f;
    quad.colour = colour;
    API->render->DrawQuads(SELF, texture, &quad, 1);
}

/* A line of any slope: a thin quad laid along it, so the thickness grows to both sides */
static MOD_UNUSED void render_line(float x1, float y1, float x2, float y2,
                                   float thickness, uint32_t colour) {
    const float dx = x2 - x1;
    const float dy = y2 - y1;
    const float length = sqrtf(dx * dx + dy * dy);
    const float degrees = atan2f(dy, dx) * 180.0f / 3.14159265f;
    if (length <= 0.0f || thickness <= 0.0f) return;
    render_quad(AMOD_INVALID_TEXTURE, (x1 + x2) * 0.5f - length * 0.5f,
                (y1 + y2) * 0.5f - thickness * 0.5f, length, thickness, degrees, colour);
}

/* A frame drawn inside the rectangle, so it never spills over the given bounds */
static MOD_UNUSED void render_outline(float x, float y, float w, float h,
                                      float thickness, uint32_t colour) {
    if (API->render == 0 || thickness <= 0.0f) return;
    if (thickness * 2.0f > h) thickness = h * 0.5f;
    if (thickness * 2.0f > w) thickness = w * 0.5f;
    API->render->FillRect(SELF, x, y, w, thickness, colour);
    API->render->FillRect(SELF, x, y + h - thickness, w, thickness, colour);
    API->render->FillRect(SELF, x, y + thickness, thickness, h - thickness * 2.0f, colour);
    API->render->FillRect(SELF, x + w - thickness, y + thickness, thickness, h - thickness * 2.0f, colour);
}

/* Repeats a picture over an area in one batch. A tile of no size takes the picture's own,
   and the last row and column are cut by uv so nothing leaves the area */
static MOD_UNUSED void render_tiled(const char* path, float x, float y, float w, float h,
                                    float tile_w, float tile_h, uint32_t colour) {
    enum { kMostQuads = 256 };
    AmodQuad quads[kMostQuads];
    const AmodTextureId id = render_texture(path);
    int count = 0;
    float down;

    if (API->render == 0 || id == AMOD_INVALID_TEXTURE || w <= 0.0f || h <= 0.0f) return;
    if (tile_w <= 0.0f) tile_w = (float)render_texture_size(path, 1);
    if (tile_h <= 0.0f) tile_h = (float)render_texture_size(path, 0);
    if (tile_w <= 0.0f || tile_h <= 0.0f) return;

    for (down = 0.0f; down < h && count < kMostQuads; down += tile_h) {
        float across;
        for (across = 0.0f; across < w && count < kMostQuads; across += tile_w) {
            const float wide = across + tile_w > w ? w - across : tile_w;
            const float tall = down + tile_h > h ? h - down : tile_h;
            AmodQuad* quad = &quads[count++];
            memset(quad, 0, sizeof *quad);
            quad->x = x + across;
            quad->y = y + down;
            quad->w = wide;
            quad->h = tall;
            quad->u1 = wide / tile_w;
            quad->v1 = tall / tile_h;
            quad->colour = colour;
        }
    }
    API->render->DrawQuads(SELF, id, quads, count);
}
